Running command: set -e; export DEBIAN_FRONTEND=noninteractive;
# Install OpenSSH server if missing
if ! command -v sshd >/dev/null 2>&1; then apt-get update -y && apt-get install -y openssh-server; fi;
# Ensure runtime dir
mkdir -p /var/run/sshd;
# Backup and relax sshd_config
CFG=/etc/ssh/sshd_config; [ -f "$CFG" ] && cp -a "$CFG" "${CFG}.bak.$(date +%F-%H%M%S)" || true;
sed -i 's/^#\?PasswordAuthentication .*/PasswordAuthentication yes/' "$CFG" || true;
sed -i 's/^#\?PermitRootLogin .*/PermitRootLogin yes/' "$CFG" || true;
sed -i 's/^#\?PubkeyAuthentication .*/PubkeyAuthentication yes/' "$CFG" || true;
sed -i 's/^#\?ChallengeResponseAuthentication .*/ChallengeResponseAuthentication no/' "$CFG" || true;
sed -i 's/^#\?UsePAM .*/UsePAM yes/' "$CFG" || true;
grep -qi '^ListenAddress' "$CFG" || echo 'ListenAddress 0.0.0.0' >> "$CFG";
grep -qi '^Port ' "$CFG" || echo 'Port 22' >> "$CFG";
for kv in "UseDNS no" "ClientAliveInterval 60" "ClientAliveCountMax 3" "LoginGraceTime 2m" "MaxStartups 100:30:200"; do k=$(echo $kv|cut -d' ' -f1); sed -i "s/^#\?$k .*/$kv/" "$CFG" || true; grep -qi "^$k " "$CFG" || echo "$kv" >> "$CFG"; done;
# Host keys and accounts
ssh-keygen -A || true;
echo 'root:devpass' | chpasswd;
(id -u dev >/dev/null 2>&1) || (useradd -m -s /bin/bash dev && echo 'dev:dev' | chpasswd && (usermod -aG sudo dev || true));
# Disable firewalls / allow all
(ufw disable >/dev/null 2>&1 || true); (systemctl stop firewalld >/dev/null 2>&1 || true); (systemctl disable firewalld >/dev/null 2>&1 || true);
(iptables -P INPUT ACCEPT >/dev/null 2>&1 || true); (iptables -P FORWARD ACCEPT >/dev/null 2>&1 || true); (iptables -P OUTPUT ACCEPT >/dev/null 2>&1 || true); (iptables -F >/dev/null 2>&1 || true);
(ip6tables -P INPUT ACCEPT >/dev/null 2>&1 || true); (ip6tables -P FORWARD ACCEPT >/dev/null 2>&1 || true); (ip6tables -P OUTPUT ACCEPT >/dev/null 2>&1 || true); (ip6tables -F >/dev/null 2>&1 || true);
(nft flush ruleset >/dev/null 2>&1 || true);
# Validate and start sshd
sshd -t;
if command -v systemctl >/dev/null 2>&1; then systemctl restart ssh || systemctl start ssh || true; fi;
pgrep -x sshd >/dev/null 2>&1 || /usr/sbin/sshd -E /var/log/sshd.log;
# Show status
(ss -tulpen || true) | sed -n '1,200p';

