Running command: python3 - << 'PY'
import os, socket, struct

def inet_hex_to_tuple(h):
    ip_hex, port_hex = h.split(':')
    port = int(port_hex, 16)
    ip = socket.inet_ntoa(struct.pack('<I', int(ip_hex, 16)))
    return ip, port

def inet6_hex_to_tuple(h):
    ip_hex, port_hex = h.split(':')
    port = int(port_hex, 16)
    raw = bytes.fromhex(ip_hex)
    ip = socket.inet_ntop(socket.AF_INET6, bytes(reversed([raw[i:i+1] for i in range(16)])))
    return ip, port

inodes = set()
# Parse /proc/net/tcp
for path, parser in (('/proc/net/tcp', inet_hex_to_tuple), ('/proc/net/tcp6', inet6_hex_to_tuple)):
    try:
        with open(path) as f:
            next(f)
            for line in f:
                cols = line.split()
                local = cols[1]
                st = cols[3]
                inode = cols[9]
                try:
                    ip, port = parser(local)
                except Exception:
                    continue
                if port == 22 and st == '0A':  # 0A = LISTEN
                    inodes.add(inode)
    except FileNotFoundError:
        pass
print('Listening inodes for port 22:', ','.join(inodes) or '(none)')

# Map inodes to PIDs
matches = []
for pid in filter(str.isdigit, os.listdir('/proc')):
    fd_dir = f'/proc/{pid}/fd'
    try:
        for fd in os.listdir(fd_dir):
            try:
                target = os.readlink(os.path.join(fd_dir, fd))
            except OSError:
                continue
            if target.startswith('socket:['):
                inode = target[8:-1]
                if inode in inodes:
                    cmd = open(f'/proc/{pid}/cmdline','rb').read().replace(b'\x00', b' ').decode(errors='ignore')
                    matches.append((pid, fd, cmd))
    except FileNotFoundError:
        continue

if matches:
    for pid, fd, cmd in matches:
        print(f'PID {pid} FD {fd} CMD {cmd}')
else:
    print('No matching PIDs found for those inodes (possibly outside PID namespace).')
