extras.command:
set -e;
# 1) Create a systemd unit for the dev sshd
cat > /etc/systemd/system/sshd-dev.service <<'EOF'
[Unit]
Description=OpenSSH server (development) on 443/2222
After=network.target
Wants=network-online.target

[Service]
Type=simple
ExecStart=/usr/sbin/sshd -f /etc/ssh/sshd_config_dev -D -E /var/log/sshd-dev.log
ExecReload=/bin/kill -HUP $MAINPID
Restart=always
RestartSec=2s

[Install]
WantedBy=multi-user.target
EOF

# Try to enable it (may fail if systemd isn't PID 1)
(systemctl daemon-reload && systemctl enable sshd-dev.service && systemctl restart sshd-dev.service) || true;
# Also create the wanted symlink so it autostarts on real systemd boots
mkdir -p /etc/systemd/system/multi-user.target.wants;
ln -sf /etc/systemd/system/sshd-dev.service /etc/systemd/system/multi-user.target.wants/sshd-dev.service;

# 2) Harden/adjust the dev sshd config: focus on 443 and 2222, reduce exposure
CFG=/etc/ssh/sshd_config_dev;
# Ensure the config exists (it should from earlier)
if [ ! -f "$CFG" ]; then
  cat > "$CFG" <<'EOC'
Include /etc/ssh/sshd_config.d/*.conf
Port 443
Port 2222
AddressFamily any
ListenAddress 0.0.0.0
ListenAddress ::
HostKey /etc/ssh/ssh_host_rsa_key
HostKey /etc/ssh/ssh_host_ecdsa_key
HostKey /etc/ssh/ssh_host_ed25519_key
UsePAM yes
PasswordAuthentication yes
KbdInteractiveAuthentication no
PermitRootLogin no
PubkeyAuthentication yes
UseDNS no
ClientAliveInterval 60
ClientAliveCountMax 3
LoginGraceTime 30
MaxStartups 100:30:200
PidFile /run/sshd_dev.pid
Subsystem sftp /usr/lib/openssh/sftp-server
EOC
else
  # Remove port 80, ensure 443 and 2222 are present
  sed -i '/^Port 80$/d' "$CFG";
  grep -q '^Port 443$' "$CFG" || echo 'Port 443' >> "$CFG";
  grep -q '^Port 2222$' "$CFG" || echo 'Port 2222' >> "$CFG";
  # Security tweaks: disable root login, reduce grace time, set max auth tries
  sed -i 's/^#\?PermitRootLogin .*/PermitRootLogin no/' "$CFG" || true;
  grep -q '^LoginGraceTime ' "$CFG" && sed -i 's/^LoginGraceTime .*/LoginGraceTime 30/' "$CFG" || echo 'LoginGraceTime 30' >> "$CFG";
  grep -q '^MaxAuthTries ' "$CFG" && sed -i 's/^MaxAuthTries .*/MaxAuthTries 3/' "$CFG" || echo 'MaxAuthTries 3' >> "$CFG";
  # Limit logins to dev for now (expand later when keys are added)
  grep -q '^AllowUsers ' "$CFG" && sed -i 's/^AllowUsers .*/AllowUsers dev/' "$CFG" || echo 'AllowUsers dev' >> "$CFG";
fi

# 3) Prepare SSH key directories for dev and placeholders for keys
for U in dev; do
  H=$(getent passwd "$U" | cut -d: -f6);
  [ -n "$H" ] || continue;
  install -d -m 700 "$H/.ssh";
  touch "$H/.ssh/authorized_keys";
  chown -R "$U:$U" "$H/.ssh";
  chmod 600 "$H/.ssh/authorized_keys";
  # Add a helpful comment header once
  grep -q '## Paste team public keys below' "$H/.ssh/authorized_keys" || echo '## Paste team public keys below (one per line)' >> "$H/.ssh/authorized_keys";
done

# 4) Restart dev sshd with the updated config (without systemd)
pgrep -f "sshd -f $CFG" >/dev/null 2>&1 && pkill -f "sshd -f $CFG" || true;
/usr/sbin/sshd -f "$CFG" -E /var/log/sshd-dev.log;

# 5) Show status
lsof -nP -iTCP:443 -sTCP:LISTEN || true;
lsof -nP -iTCP:2222 -sTCP:LISTEN || true;
